// v1.10.9: captura prioritária dos controles de tarefa. Evita que o cartão pai (role=button) ou gestos do calendário interceptem os botões internos.
main.addEventListener('click',e=>{
 const control=e.target instanceof Element?e.target.closest('[data-toggle],[data-detail]'):null;
 if(!control||!main.contains(control))return;
 if(control.hasAttribute('data-toggle')){
  const id=control.getAttribute('data-toggle'),task=state.tasks.find(x=>x.id===id);
  if(!task)return;
  const date=control.getAttribute('data-day')||iso(today()),key=dateKey(task,atDate(date));
  state.completed[key]=!state.completed[key];persist();render();
  notify(state.completed[key]?'Tarefa concluída':'Tarefa marcada como pendente');
 }else{
  const id=control.getAttribute('data-detail');
  if(!id)return;
  detailId=id;window.__detailDate=control.getAttribute('data-day')||iso(today());render();
 }
 e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();
},true);
main.addEventListener('click',e=>{const b=e.target.closest('[data-theme-choice]');if(!b)return;state.accent=b.dataset.themeChoice;localStorage.setItem(KEY+'-theme-selected','1');persist();render();notify('Tema aplicado: '+THEMES.find(t=>t[0]===state.accent)[1]);});
